script:
carrier_event = {
	id = akx.9541
	title = akx.9541.name
	desc = akx.9541.desc
	picture = GFX_evt_colony_settlement
	location = root

	is_triggered_only = yes

	immediate = {
		# Other empires react to purge according to action.21
		weighted_random_owned_pop_group = {
			limit = {
				exists = planet
				planet = { is_same_value = root }
			}
			save_event_target_as = purged_species
		}
		every_country = {
			limit = {
				has_communications = root.owner
				NOT = { is_country = root.owner }
				NOT = { is_same_species = root.owner }
				NOT = { has_ai_personality_behaviour = purger }
				OR = {
					is_country_type = default
					has_ai_personality = awakened_fallen_empire_xenophile
				}
			}
			add_opinion_modifier = { who = root.owner modifier = opinion_genocidal }
		}
		every_country = {
			limit = {
				has_communications = root.owner
				NOT = { is_country = root.owner }
				is_same_species = event_target:purged_species
			}
			add_opinion_modifier = { who = root.owner modifier = opinion_genocidal_our_species }
		}
	}

	after = {
		hidden_effect = {
			destroy_colony = yes
		}
	}

	option = {
		name = akx.9541.a
		owner = {
			add_monthly_resource_mult = {
				resource = unity
				value = @tier3unityreward
			}
		}
	}

	option = {
		name = akx.9541.b
		owner = {
			add_monthly_resource_mult = {
				resource = influence
				value = 24
				min = 200
				max = 1000
			}
			add_modifier = {
				modifier = unity_reduction_akx_9541
				days = 1800
			}
		}
	}
}

carrier_event = {
	id = akx.9545
	title = akx.9545.name
	desc = akx.9545.desc
	picture = GFX_evt_colony_settlement
	location = root

	is_triggered_only = yes

	after = {
		owner = {
			add_monthly_resource_mult = {
				resource = physics_research
				value = 8
				min = 200
				max = 1000
			}
			if = {
				limit = {
					has_technology = tech_akx_worm_1
				}
				# nothing
			}
			else = {
				add_tech_progress = {
					tech = tech_akx_worm_1
					progress = 0.1
				}
				if = {
					limit = {
						NOT = {
							has_tech_option = tech_akx_worm_1
						}
					}
					add_research_option = tech_akx_worm_1
				}
			}
		}
	}

	option = {
		name = akx.9545.a
	}
	option = {
		name = akx.9545.b
	}
}

